prompt --application/shared_components/user_interface/shortcuts/welcome_text
begin
wwv_flow_imp_shared.create_shortcut(
 p_id=>wwv_flow_imp.id(43392752526878389572)
,p_shortcut_name=>'WELCOME_TEXT'
,p_shortcut_type=>'HTML_TEXT'
,p_version_scn=>1
,p_shortcut=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<head>   ',
'<meta name="viewport" content="width=device-width, initial-scale=1.0">',
'    <title>Welcome Page</title>',
'    <style>',
'        body {',
'            margin: 0;',
'            padding: 0;',
'            background-color: #f4f4f4;',
'            display: flex;',
'            align-items: center;',
'            justify-content: center;',
'            height: 100vh;',
'        }',
'',
'        .welcome-container {',
'            text-align: center;',
'            background-color: #fff;',
'            padding: 20px;',
'            border-radius: 10px;',
'            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);',
'        }',
'',
'        h1 {',
'            color: #333;',
'            font-size: 2em;',
'            margin-bottom: 20px;',
'        }',
'',
'        p {',
'            color: #666;',
'            font-size: 1.2em;',
'            margin-bottom: 30px;',
'        }',
'',
'        .btn {',
'            display: inline-block;',
'            padding: 10px 20px;',
'            background-color: #4caf50;',
'            color: #fff;',
'            text-decoration: none;',
'            border-radius: 5px;',
'            font-size: 1em;',
'            transition: background-color 0.3s;',
'        }',
'',
'        .btn:hover {',
'            background-color: #45a049;',
'        }',
'    </style>',
'    <script>',
'        function hideWelcomeContainer() {',
'            document.querySelector(''.welcome-container'').style.display = ''none'';',
'            closeModal(''WELCOME_DIALG'');',
'        }',
'    </script>',
'</head>',
'<body>',
'    <div class="welcome-container">',
'        <h1>Hello! &APP_USER. Welcome to Our Website</h1>',
'        <p>Explore our amazing features and discover what awaits you!</p>',
'        <a href="#" class="btn" onclick="hideWelcomeContainer()">Get Started</a>',
'    </div>',
'</body>',
'',
''))
);
end;
/
