wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(43311338537456551849)
,p_plug_name=>unistr('\09A1\09CD\09AF\09BE\09B6\09AC\09CB\09B0\09CD\09A1')
,p_parent_plug_id=>wwv_flow_imp.id(43311337933124551843)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleA'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH summary AS (',
'    SELECT',
'        SUM(CASE WHEN COST_TYPE = ''CR'' THEN COST_AMOUNT ELSE 0 END) AS total_credit,',
'        SUM(CASE WHEN COST_TYPE = ''DR'' THEN COST_AMOUNT ELSE 0 END) AS total_debit',
'    FROM COSTING_LIST',
'),',
'installment AS (',
'    SELECT SUM(installment_amount) AS total_installment ,count(*) TOT_NO_OF_INSTALLMENT',
'    FROM MEM_INSTALLMENT_COLLECTION',
'),',
'members AS (',
'    SELECT COUNT(*) total_members',
'    FROM SOMITEE_MEMBER_LIST',
'    where NVL(ACTIVE_FLAG,''N'')=''Y''',
')',
unistr('SELECT ''\09B8\09B0\09CD\09AC\09AE\09CB\099F \09A8\0997\09A6 \09B8\0982\0997\09CD\09B0\09B9'' AS card_title,'),
'       TO_CHAR(s.total_installment, ''999G999G999D00'') AS card_subtitle,',
'       ''fa-plus'' AS card_icon',
'FROM installment s',
'',
'UNION ALL',
'',
unistr('SELECT ''\09B8\09B0\09CD\09AC\09AE\09CB\099F \0986\09A6\09BE\09DF\0995\09C3\09A4 \0995\09BF\09B8\09CD\09A4\09BF'' AS card_title,'),
'       TO_CHAR(TOT_NO_OF_INSTALLMENT,''9999999900'') AS card_subtitle,',
'       ''fa-plus'' AS card_icon',
'FROM installment s',
'',
'UNION ALL',
'',
unistr('SELECT ''\09B8\09B0\09CD\09AC\09AE\09CB\099F \099C\09AE\09BE (\09AC\09CD\09AF\09BE\0982\0995)'','),
'       TO_CHAR(s.total_credit, ''999G999G999D00''),',
'       ''fa-minus''',
'FROM summary s',
'',
'UNION ALL',
'',
unistr('SELECT ''\09B8\09B0\09CD\09AC\09AE\09CB\099F \09AC\09CD\09AF\09DF'','),
'       TO_CHAR(s.total_debit, ''999G999G999D00''),',
'       ''fa-minus''',
'FROM summary s',
'',
'UNION ALL',
'',
unistr('SELECT ''\09AC\09B0\09CD\09A4\09AE\09BE\09A8 \0985\09B0\09CD\09A5\09C7\09B0 \09AA\09B0\09BF\09AE\09BE\09A3'','),
'       TO_CHAR(NVL(i.total_installment,0)-s.total_debit, ''999G999G999D00''),',
'       ''fa-money''',
'FROM summary s, installment i',
'',
'UNION ALL',
'',
unistr('SELECT ''\09AC\09B0\09CD\09A4\09AE\09BE\09A8 \09B8\09A6\09B8\09CD\09AF \09B8\0982\0996\09CD\09AF\09BE'','),
'       TO_CHAR(m.total_members),',
'       ''fa-users-alt''',
'FROM members m;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
