,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function validateField(fieldId) {',
'   // get the field value',
'   var fieldValue = document.getElementById(fieldId).value;',
'   var errorMessage = ''Special Character are Not allowed'';',
'   var verrorMessage = ''Letters are not allowed. Please enter a valid number.'';',
'   // regular expression to match special characters',
'   var pattern = /[/!@#$%^&*(),.?":{}|<>]/;',
'   var letters = /^[A-Za-z]+$/;',
'',
'   // check if the field value contains any special characters',
'   if (pattern.test(fieldValue)) {',
'      document.getElementById(fieldId).value = fieldValue.replace(pattern,'''');',
'      apex.message.showErrors([{',
'         type: "error",',
'         location: ["inline"],',
'         pageItem: fieldId,',
'         message: errorMessage,',
'         unsafe: false',
'      }]);',
'      return false;',
'   }',
'   else if (letters.test(fieldValue)){',
'        document.getElementById(fieldId).value = fieldValue.replace(letters,'''');',
'        apex.message.showErrors([{',
'         type: "error",',
'         location: ["inline"],',
'         pageItem: fieldId,',
'         message: verrorMessage,',
'         unsafe: false',
'      }]);',
'    return false;',
'   }',
'    else {',
'      // remove error message',
'        apex.message.clearErrors();',
'      return true;',
'   }',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
);
