,p_name=>'Show Fine Amount'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P5_MEMBER_NO'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
