wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(25085105180153947934)
,p_event_id=>wwv_flow_imp.id(25085105019751947933)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'SELECT (tot_ins_rest-1) * 100',
'      INTO :P5_FINE_AMOUNT',
'      FROM (  SELECT   ROUND (',
'                           MONTHS_BETWEEN (',
'                               SYSDATE + (LAST_DAY (SYSDATE) - TRUNC (SYSDATE)),',
'                               TO_DATE (''2022-10-1'', ''YYYY-MM-DD'')))',
'                     - COUNT (*)    tot_ins_rest',
'                FROM MEM_INSTALLMENT_COLLECTION A',
'                     INNER JOIN SOMITEE_MEMBER_LIST B',
'                         ON (A.MEMBER_NO = B.MEMBER_NO)',
'               WHERE A.MEMBER_NO = :P5_MEMBER_NO',
'            GROUP BY B.MEMBER_NAME, A.MEMBER_NO);',
'',
'            IF :P5_FINE_AMOUNT < 0 THEN :P5_FINE_AMOUNT := 0;',
'            END IF;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        NULL;',
'END;'))
,p_attribute_02=>'P5_MEMBER_NO'
,p_attribute_03=>'P5_FINE_AMOUNT'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(25017190686431610013)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Process form \0995\09BF\09B8\09CD\09A4\09BF \099C\09AE\09BE \09AB\09B0\09CD\09AE')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vExist   NUMBER;',
'BEGIN',
'    FOR i IN 1 .. :P5_NO_OF_MONTH',
'    LOOP',
'        BEGIN',
'            SELECT COUNT (*)',
'              INTO vExist',
'              FROM MEM_INSTALLMENT_COLLECTION',
'             WHERE     MEMBER_NO = :P5_MEMBER_NO',
'                    AND to_char(INSTALLMENT_DATE,''YYYYMM'') =TO_CHAR (to_date(:P5_START_MONTH),''YYYYMM'');',
'                       --TO_DATE ( :P5_START_MONTH) + (i * 30 - 1);',
'        END;',
'',
'        IF vExist > 0',
'        THEN',
'            Raise_application_error (',
'                -20001,',
unistr('                   ''\09AC\09B0\09CD\09A4\09AE\09BE\09A8 [ '''),
'                || TO_CHAR (TO_DATE ( :P5_START_MONTH), ''Month RRRR'')',
unistr('                || ''] \09AE\09BE\09B8\09C7\09B0 \0995\09BF\09B8\09CD\09A4\09BF \09AA\09B0\09BF\09B6\09CB\09A7 \0995\09B0\09BE \0986\099B\09C7'');'),
'        END IF;',
'',
'        INSERT INTO MEM_INSTALLMENT_COLLECTION (INSTALLMENT_ID,',
'                                                MEMBER_NO,',
'                                                INSTALLMENT_DATE,',
'                                                INSTALLMENT_AMOUNT,',
'                                                PAYMENT_VIA_ID,',
'                                                PAYMENT_REFERENCE)',
'             VALUES (BAL_SL_SEQ.NEXTVAL,',
'                     :P5_MEMBER_NO,',
'                     TO_DATE ( :P5_START_MONTH), --+ (i * 30 - 1),',
'                     :P5_INSTALLMENT_AMOUNT,',
'                     :P5_PAYMENT_VIA_ID,',
'                     :P5_PAYMENT_REFERENCE);',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>25017190686431610013
);
