 p_id=>wwv_flow_imp.id(17161910047987731230)
,p_name=>unistr('\099C\09AE\09BE\0995\09C3\09A4 \0985\09B0\09CD\09A5')
,p_region_name=>'EXPORT_REPORT'
,p_template=>4072358936313175081
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT member_name         AS "\09B8\09A6\09B8\09CD\09AF\09C7\09B0 \09A8\09BE\09AE",'),
unistr('       tot_ins_paid        AS "\09AE\09CB\099F \0986\09A6\09BE\09DF\0995\09C3\09A4 \0995\09BF\09B8\09CD\09A4\09BF",'),
unistr('       tot_ins_amount      AS "\09AE\09CB\099F \099C\09AE\09BE",'),
unistr('       tot_ins_no          AS "\09AE\09CB\099F \0995\09BF\09B8\09CD\09A4\09BF",'),
'       CASE ',
'           WHEN tot_ins_rest < 0 THEN 0 ',
'           ELSE tot_ins_rest ',
unistr('       END                 AS "\09AC\0995\09C7\09DF\09BE \0995\09BF\09B8\09CD\09A4\09BF",'),
'       CASE ',
'           WHEN tot_ins_rest < 0 THEN ABS(tot_ins_rest) ',
'           ELSE 0 ',
unistr('       END                 AS "\0985\0997\09CD\09B0\09C0\09AE \099C\09AE\09BE",'),
'       CASE ',
'           WHEN tot_ins_rest > 0 THEN ''red'' ',
'           ELSE ''green'' ',
'       END                 AS color,',
unistr('       expense_category    AS "\0996\09B0\099A \0995\09CD\09AF\09BE\099F\09BE\0997\09B0\09BF",'),
unistr('       cost_amount         AS "\0996\09B0\099A\09C7\09B0 \09AA\09B0\09BF\09AE\09BE\09A3",'),
'       (tot_ins_amount - NVL(cost_amount,0)) ',
unistr('                            AS "\0985\09AC\09B6\09BF\09B7\09CD\099F \099F\09BE\0995\09BE"'),
'FROM (',
'    SELECT ',
'        B.MEMBER_NAME || '' -- '' || A.MEMBER_NO    AS member_name,',
'        COUNT(*)                                  AS tot_ins_paid,',
'        SUM(A.INSTALLMENT_AMOUNT)                 AS tot_ins_amount,',
'        -- total installments expected up to this month',
'        ROUND(',
'            MONTHS_BETWEEN(',
'                LAST_DAY(SYSDATE), ',
'                DATE ''2022-10-01''',
'            )',
'        )                                         AS tot_ins_no,',
'        ROUND(',
'            MONTHS_BETWEEN(',
'                LAST_DAY(SYSDATE), ',
'                DATE ''2022-10-01''',
'            )',
'        ) - COUNT(*)                              AS tot_ins_rest,',
'        CASE ',
unistr('            WHEN C.EXPENSE_CATEGORY = ''L'' THEN ''\09B2\09CB\09A8''  '),
unistr('            WHEN C.EXPENSE_CATEGORY = ''C'' THEN ''<b style="color:red">\09B8\09A6\09B8\09CD\09AF\09AA\09A6 \09A5\09C7\0995\09C7 \0985\09AC\09CD\09AF\09B9\09A4\09BF</b>'''),
unistr('            WHEN C.EXPENSE_CATEGORY = ''W'' THEN ''\09B6\09C1\09A7\09C1 \0989\09A4\09CD\09A4\09CB\09B2\09A8''  '),
unistr('            ELSE ''\09AA\09CD\09B0\09AF\09CB\099C\09CD\09AF \09A8\09DF'' '),
'        END                                       AS expense_category,',
'        C.COST_AMOUNT',
'    FROM MEM_INSTALLMENT_COLLECTION A',
'    INNER JOIN SOMITEE_MEMBER_LIST B ',
'        ON A.MEMBER_NO = B.MEMBER_NO',
'    LEFT JOIN COSTING_LIST C ',
'        ON B.MEM_ID = C.MEMBER_ID',
'    GROUP BY B.MEMBER_NAME, A.MEMBER_NO, C.EXPENSE_CATEGORY, C.COST_AMOUNT',
');',
''))
