'DECLARE',
'    l_export       apex_data_export.t_export;',
'    l_region_id    number;',
'BEGIN',
'   SELECT region_id into l_region_id',
'     FROM apex_application_page_regions',
'    WHERE application_id = :APP_ID',
'      and page_id = :APP_PAGE_ID',
'      and static_id = ''EXPORT_REPORT'';',
'    ',
'    l_export := apex_region.export_data (',
'         p_format       => CASE WHEN :P6_FILE_TYPE=''P'' THEN apex_data_export.c_format_pdf',
'                                WHEN :P6_FILE_TYPE=''C'' THEN apex_data_export.c_format_csv',
'                                ELSE apex_data_export.c_format_html END,',
'         p_page_id      => :APP_PAGE_ID,',
'         p_region_id    => l_region_id );',
'         ',
'    apex_data_export.download( l_export );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>18228451811144916231
);
