wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(25085104234584947925)
,p_name=>'Get Member Details'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P9_MEMBER_ID'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(25085104371531947926)
,p_event_id=>wwv_flow_imp.id(25085104234584947925)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT member_name',
unistr('               AS "\09B8\09A6\09B8\09CD\09AF\09C7\09B0 \09A8\09BE\09AE",'),
'           tot_ins_paid',
unistr('               AS "\09AE\09CB\099F \0986\09A6\09BE\09DF\0995\09C3\09A4 \0995\09BF\09B8\09CD\09A4\09BF",'),
'           to_char(tot_ins_amount,''999G999G999G999G990D00'')',
unistr('               AS "\09AE\09CB\099F \099C\09AE\09BE",'),
'           tot_ins_no',
unistr('               AS "\09AE\09CB\099F \0995\09BF\09B8\09CD\09A4\09BF",'),
'           CASE WHEN tot_ins_rest < 0 THEN 0 ELSE tot_ins_rest END',
unistr('               AS "\09AC\0995\09C7\09DF\09BE \0995\09BF\09B8\09CD\09A4\09BF",'),
'           CASE WHEN tot_ins_rest < 0 THEN ABS (tot_ins_rest) ELSE 0 END',
unistr('               AS "\0985\0997\09CD\09B0\09C0\09AE \099C\09AE\09BE"'),
'      INTO :P9_MEMBER_NAME,',
'           :P9_TOTAL_INSTALLMENT_PAID,',
'           :P9_TOTAL_BALANCE,',
'           :P9_TOTAL_INSTALLMENT,',
'           :P9_REST_INSTALLMENT,',
'           :P9_ADVANCE_INSTALL',
'      FROM (  SELECT B.MEMBER_NAME || ''--'' || A.MEMBER_NO',
'                         member_name,',
'                     COUNT (*)',
'                         tot_ins_paid,',
'                     SUM (INSTALLMENT_AMOUNT)',
'                         tot_ins_amount,',
'                     ROUND (',
'                         MONTHS_BETWEEN (',
'                             SYSDATE + (LAST_DAY (SYSDATE) - TRUNC (SYSDATE)),',
'                             TO_DATE (''2022-10-1'', ''YYYY-MM-DD'')))',
'                         tot_ins_no,',
'                       ROUND (',
'                           MONTHS_BETWEEN (',
'                               SYSDATE + (LAST_DAY (SYSDATE) - TRUNC (SYSDATE)),',
'                               TO_DATE (''2022-10-1'', ''YYYY-MM-DD'')))',
'                     - COUNT (*)',
'                         tot_ins_rest',
'                FROM MEM_INSTALLMENT_COLLECTION A',
'                     INNER JOIN SOMITEE_MEMBER_LIST B',
'                         ON (A.MEMBER_NO = B.MEMBER_NO)',
'               WHERE A.MEMBER_NO = :P9_MEMBER_ID',
'            GROUP BY B.MEMBER_NAME, A.MEMBER_NO);',
'     EXCEPTION WHEN NO_DATA_FOUND THEN ',
'     NULL;',
'END;'))
,p_attribute_02=>'P9_MEMBER_ID'
,p_attribute_03=>'P9_MEMBER_NAME,P9_TOTAL_BALANCE,P9_REST_INSTALLMENT,P9_TOTAL_INSTALLMENT,P9_TOTAL_INSTALLMENT_PAID,P9_ADVANCE_INSTALL'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
