,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ID,',
'    COST_DATE,',
'    COST_DETAILS,',
'    COST_AMOUNT,',
'    SUM(COST_AMOUNT) OVER (ORDER BY COST_DATE) AS total_collection,',
'    NULL AS difference',
'FROM ',
'    COSTING_LIST',
'',
'UNION ALL',
'',
'SELECT ',
'    NULL AS ID,',
'    NULL AS COST_DATE,',
'    ''Total Summary'' AS COST_DETAILS,',
'    (SELECT SUM(COST_AMOUNT) FROM COSTING_LIST) AS COST_AMOUNT,',
'    (SELECT SUM(installment_amount) FROM MEM_INSTALLMENT_COLLECTION) AS total_collection,',
'    (SELECT SUM(installment_amount) FROM MEM_INSTALLMENT_COLLECTION) - (SELECT SUM(COST_AMOUNT) FROM COSTING_LIST) AS difference',
'FROM ',
'    dual;',
