,p_name=>'Debit Credit '
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    CASE ',
'        WHEN GROUPING(COST_DATE) = 1 AND GROUPING(COST_DETAILS) = 1 THEN ''Grand Total''',
'        ELSE COST_DETAILS ',
'    END AS "Details",',
'    CASE ',
'        WHEN GROUPING(COST_DATE) = 0 THEN TO_CHAR(COST_DATE, ''DD-MON-YYYY'') ',
'        ELSE NULL ',
'    END AS "Date",',
'    SUM(CASE WHEN COST_TYPE = ''DR'' THEN COST_AMOUNT ELSE 0 END) AS "Debit Amount",',
'    SUM(CASE WHEN COST_TYPE = ''CR'' THEN COST_AMOUNT ELSE 0 END) AS "Credit Amount",',
'    (SELECT SUM(installment_amount) ',
'     FROM MEM_INSTALLMENT_COLLECTION) AS "Total Collection",',
'    SUM(CASE WHEN COST_TYPE = ''CR'' THEN COST_AMOUNT ELSE 0 END) - ',
'    (SELECT SUM(installment_amount) ',
'     FROM MEM_INSTALLMENT_COLLECTION) AS "Difference"',
'FROM ',
'    COSTING_LIST',
'GROUP BY ',
'    ROLLUP(COST_DATE, COST_DETAILS)',
'HAVING ',
'    NOT (GROUPING(COST_DETAILS) = 1 AND GROUPING(COST_DATE) = 0)',
'ORDER BY ',
'    COST_DATE NULLS LAST, GROUPING(COST_DETAILS), COST_DETAILS;',
''))
