'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(43311335074953551814)
,p_plug_name=>'HTML Report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>30
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vHtmlReport      CLOB;',
'    vMemberInfo      CLOB;',
'    vInstallmentList CLOB;',
'    vTotInstallments NUMBER := 0;',
'    vTotInstallAmt   NUMBER := 0;',
'BEGIN',
'    -- Fetch Member Info',
'    FOR I IN (',
'        SELECT member_no, MEMBER_NAME, email, mobile_no, address',
'        FROM SOMITEE_MEMBER_LIST',
'        WHERE MEMBER_NO = ''20220025''',
'    ) LOOP',
'        vMemberInfo := ''',
'        <div class="mb-6">',
unistr('            <h2 class="text-xl font-semibold text-gray-800 mb-3 border-b pb-1 border-gray-300">\09B8\09A6\09B8\09CD\09AF\09C7\09B0 \09B8\09BE\09A7\09BE\09B0\09A3 \09A4\09A5\09CD\09AF</h2>'),
'            <div class="grid grid-cols-2 gap-4 text-sm text-gray-700">',
unistr('                <p><strong>\09B8\09A6\09B8\09CD\09AF\09C7\09B0 \09A8\09BE\09AE:</strong> '' || i.MEMBER_NAME || ''</p>'),
unistr('                <p><strong>\09B8\09A6\09B8\09CD\09AF \09A8\09BE\09AE\09CD\09AC\09BE\09B0:</strong> '' || i.member_no || ''</p>'),
unistr('                <p><strong>\09A0\09BF\0995\09BE\09A8\09BE:</strong> '' || i.address || ''</p>'),
unistr('                <p><strong>\0987-\09AE\09C7\0987\09B2:</strong> '' || i.email || ''</p>'),
unistr('                <p><strong>\09AE\09CB\09AC\09BE\0987\09B2 \09A8\09BE\09AE\09CD\09AC\09BE\09B0:</strong> '' || i.mobile_no || ''</p>'),
'            </div>',
'        </div>'';',
'    END LOOP;',
'',
'    -- Fetch Installment Collection List',
'    FOR INS IN (',
'        SELECT INSTALLMENT_ID, MEMBER_NO, INSTALLMENT_DATE, INSTALLMENT_AMOUNT,',
'               PAYMENT_VIA_ID, FINE_AMOUNT, PAYMENT_REFERENCE',
'        FROM WKSP_AYUBWP.MEM_INSTALLMENT_COLLECTION',
'        WHERE MEMBER_NO = ''20220025''',
'        ORDER BY INSTALLMENT_ID ASC',
'    ) LOOP',
'        vTotInstallments := vTotInstallments + 1;',
'        vTotInstallAmt   := vTotInstallAmt + INS.INSTALLMENT_AMOUNT;',
'',
'        vInstallmentList := vInstallmentList || ''',
'        <tr>',
'            <td class="border border-gray-300 px-4 py-2">'' || INS.INSTALLMENT_ID || ''</td>',
'            <td class="border border-gray-300 px-4 py-2">'' || INS.INSTALLMENT_DATE || ''</td>',
'            <td class="border border-gray-300 px-4 py-2 text-right">'' || TO_CHAR(INS.INSTALLMENT_AMOUNT, ''999G999G999G999G990D00'') || ''</td>',
'            <td class="border border-gray-300 px-4 py-2 text-center text-green-700 font-semibold">'' || INS.PAYMENT_VIA_ID || ''</td>',
'            <td class="border border-gray-300 px-4 py-2 text-left text-green-700 font-semibold">'' || TO_CHAR(INS.INSTALLMENT_DATE, ''Month'') || ''</td>',
'            <td class="border border-gray-300 px-4 py-2">'' || INS.PAYMENT_REFERENCE || ''</td>',
'        </tr>'';',
'    END LOOP;',
'',
'    -- Combine Full HTML Report',
'    vHtmlReport := ''',
'<div id="printableArea" class="max-w-4xl mx-auto my-12 bg-white shadow-lg rounded-lg p-10 border border-gray-300">',
'<script src="#WORKSPACE_FILES#Tailwind.css"></script>',
'',
'<style>',
'@media print {',
'  body * {',
'    visibility: hidden;',
'  }',
'  #printableArea, #printableArea * {',
'    visibility: visible;',
'  }',
'  #printableArea {',
'    position: absolute;',
'    left: 0;',
'    top: 0;',
'    width: 100%;',
'    margin: 0;',
'    padding: 0;',
'  }',
'}',
'</style>',
'',
'<div class="flex justify-between items-center border-b border-gray-300 pb-5 mb-8">',
'    <div>',
unistr('        <h1 class="text-3xl font-bold text-blue-900">\09AC\09B8\09A8\09CD\09A4\09AA\09C1\09B0 \09AA\09CD\09B0\09AC\09BE\09B8\09C0 \0995\09B2\09CD\09AF\09BE\09A3 \09B8\09AE\09BF\09A4\09BF \09E8\09E6\09E8\09E8</h1>'),
unistr('        <p class="text-gray-700 text-sm mt-1">\0995\09BF\09B8\09CD\09A4\09BF\09B0 \0986\09A6\09BE\09DF\09C7\09B0 \09AC\09BF\09AC\09B0\09A3\09BF</p>'),
'    </div>',
'    <div class="text-sm text-gray-600">',
'        <p><strong>Date:</strong> '' || TO_CHAR(SYSDATE, ''DD-MON-YYYY HH24:MI:SS'') || ''</p>',
'        <p><strong>Document No:</strong> DOC0001'' || TO_CHAR(SYSDATE, ''DDMMYYYYMISS'') || ''</p>',
'    </div>',
'</div>',
'',
''' || vMemberInfo || ''',
'',
'<div class="mb-8">',
unistr('    <h2 class="text-xl font-semibold text-gray-800 mb-3 border-b pb-1 border-gray-300">\0986\09A6\09BE\09DF\09C7\09B0 \09AC\09BF\09B8\09CD\09A4\09BE\09B0\09BF\09A4 \09A4\09A5\09CD\09AF</h2>'),
'    <div class="overflow-x-auto">',
'        <table class="min-w-full border border-gray-300 text-sm">',
'            <thead class="bg-gray-200">',
'                <tr>',
unistr('                    <th class="border border-gray-300 px-4 py-2 text-left">#\099F\09CD\09B0\09BE\099E\09CD\099C\09C7\0995\09B6\09A8 \0986\0987\09A1\09BF</th>'),
unistr('                    <th class="border border-gray-300 px-4 py-2 text-left">\0995\09BF\09B8\09CD\09A4\09BF \0986\09A6\09BE\09DF\09C7\09B0 \09A4\09BE\09B0\09BF\0996</th>'),
unistr('                    <th class="border border-gray-300 px-4 py-2 text-right">\09AA\09B0\09BF\09AE\09BE\09A8 (\099F\09BE\0995\09BE)</th>'),
unistr('                    <th class="border border-gray-300 px-4 py-2 text-left">\0986\09A6\09BE\09DF\09C7\09B0 \09AE\09BE\09A7\09CD\09AF\09AE</th>'),
unistr('                    <th class="border border-gray-300 px-4 py-2 text-left">\0986\09A6\09BE\09DF\0995\09C3\09A4 \09AE\09BE\09B8</th>'),
unistr('                    <th class="border border-gray-300 px-4 py-2 text-left">\09AE\09A8\09CD\09A4\09AC\09CD\09AF</th>'),
'                </tr>',
'            </thead>',
'            <tbody>',
'                '' || vInstallmentList || ''',
'            </tbody>',
'        </table>',
'    </div>',
'</div>',
'',
'<div class="text-sm text-gray-800 border-t border-gray-300 pt-4">',
unistr('    <p><strong>\09B8\09B0\09CD\09AC\09AE\09CB\099F \0995\09BF\09B8\09CD\09A4\09BF:</strong> '' || vTotInstallments || ''</p>'),
unistr('    <p><strong>\0995\09BF\09B8\09CD\09A4\09BF\09B0 \09AE\09CB\099F \09AA\09B0\09BF\09AE\09BE\09A8:</strong> '' || TO_CHAR(vTotInstallAmt, ''999G999G999G999G990D00'') || '' \099F\09BE\0995\09BE\0964</p>'),
'</div>',
'',
'<div class="mt-8 text-right">',
'    <button onclick="printDiv(''''printableArea'''')" class="px-6 py-2 bg-blue-800 text-white text-sm font-semibold rounded hover:bg-blue-900">Print Document</button>',
'</div>',
'',
'</div>'';',
'    ',
'    RETURN (vHtmlReport);',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_required_patch=>wwv_flow_imp.id(26121798008520632002)
);
